# -*- coding: utf-8 -*-
"""Bangla materia medica, volume 3 — written from the English source layers.

Volumes 1 and 2 (r_materia.py, r_materia2.py) were authored from the standard
literature. This volume covers remedies that had *no* Bangla picture, written by
reading the Boericke and Clarke text that now sits in assets/data/materia/ and
putting the same clinical picture into Bangla.

This is authored, not machine-translated: each entry is written from the source
in front of it, keeping Boericke's and Clarke's own emphases (the symptoms they
italicise become the কীনোট), and dropping nothing into a field that the source
does not actually support. Where a source gives only a fragment — a mineral water
with two paragraphs, say — the entry stays short rather than being padded out.

Ordered by how often the remedy appears in Kent, so the entries a case is most
likely to reach were written first and are the easiest to check against the
English text shown beside them in the app.
"""

